// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract FraudRegistry {
    mapping(address => bool) public blacklistedAddresses;
    event FraudLogged(address indexed account, uint256 riskScore, string reason);

    function flagFraudulentAccount(address account, uint256 riskScore, string memory reason) public {
        if (riskScore > 85) {
            blacklistedAddresses[account] = true;
        }
        emit FraudLogged(account, riskScore, reason);
    }

    function checkStatus(address account) public view returns (bool) {
        return blacklistedAddresses[account];
    }
}
